@startuml

enum BuildingMaterial {
  WOOD
  BRICK
  CONCRETE
}

class House {
  + Address : string
  + BuildingMaterial : BuildingMaterial
}

abstract class Basement {
  + Size : double
  + Name : string
}

class EarthBasement extends Basement {
  + Humidity : double
}

class ConcreteBasement extends Basement {
}

class SemiDetachedHouse extends House {
  + HasOwnGarden : boolean
  + WindowsCount : int
}

class Carport {
  + IsDoubleCarport : boolean
  + HasFlatRoof : boolean
}

class Garage {
  + HasAutomaticGarageDoor : boolean
}

class Company {
  + Name : string
  + Address : string
}

class JobLog {
  + Hours : int
  + Price : double
}

House "1" *-- "0..1" Basement
House "1" -- "*" Company
House "1" -- "*" JobLog
Company "1" -- "*" JobLog
SemiDetachedHouse "1" -- "2" Carport
SemiDetachedHouse "1" -- "0..1" Garage

@enduml

